// Not part of the configured E2E suite; run with plain `node`. Uses an absolute require path
// to playwright-core so resolution doesn't depend on this script's own on-disk location.
//
// v2 fix: 'networkidle' never resolves against Storybook's webpack-dev-server (persistent HMR
// websocket keeps the network "active" forever) - each goto was eating a full 30s timeout, and
// the one unguarded goto (in probeDefaultBoundaries) threw and killed the script before any
// results printed. Switched to waitUntil:'load' + an explicit wait for real rendered content
// (the product-name <h2>, present in every ProductItem story including GiftCard). Also now logs
// each story's result immediately instead of batching everything to the very end.
const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core');

const BASE = 'http://localhost:6006/iframe.html';
