  { key: 'Default', id: 'commerce-productitem--default', expectStepper: true },
  { key: 'MultipleItems', id: 'commerce-productitem--multiple-items', expectStepper: true },
  { key: 'GiftCard', id: 'commerce-productitem--gift-card', expectStepper: false },
  { key: 'WithErrorMessage', id: 'commerce-productitem--with-error-message', expectStepper: true },
  { key: 'WithWarningMessage', id: 'commerce-productitem--with-warning-message', expectStepper: true },
  { key: 'WithDiscountLabel', id: 'commerce-productitem--with-discount-label', expectStepper: true },
];

async function waitForSettled(page) {
  try {
    await page.getByRole('heading', { level: 2 }).first().waitFor({ state: 'visible', timeout: 10000 });
  } catch (e) {
    // Swallow - absence itself is meaningful and will show up in the caller's own checks below.
  }
  await page.waitForTimeout(300);
}

async function probeStory(browser, story) {
  const url = `${BASE}?id=${story.id}&viewMode=story`;
  const page = await browser.newPage();
  const consoleMsgs = [];
  const pageErrors = [];
  page.on('console', (msg) => consoleMsgs.push({ type: msg.type(), text: msg.text() }));
  page.on('pageerror', (err) => pageErrors.push(String(err && err.stack ? err.stack : err)));

  let navError = null;
  try {
    await page.goto(url, { waitUntil: 'load', timeout: 20000 });
  } catch (e) {
    navError = String(e);
  }
  await waitForSettled(page);

  const dec = page.getByRole('button', { name: 'Decrease quantity' });
  const inc = page.getByRole('button', { name: 'Increase quantity' });
  const decCount = await dec.count();
  const incCount = await inc.count();
  const decVisibleFlags = [];
  const incVisibleFlags = [];
  for (let i = 0; i < decCount; i++) decVisibleFlags.push(await dec.nth(i).isVisible());
  for (let i = 0; i < incCount; i++) incVisibleFlags.push(await inc.nth(i).isVisible());

  const headingCount = await page.getByRole('heading', { level: 2 }).count();
  const bodyText = await page.evaluate(() => document.body.innerText).catch(() => '');
  const errorOverlayHit = /exception|error boundary|something went wrong|uncaught/i.test(bodyText);

  await page.close();

  return {
    key: story.key,
    url,
    navError,
    headingCount,
    decCount,
    incCount,
    decVisibleFlags,
    incVisibleFlags,
    consoleMsgs,
    pageErrors,
    errorOverlayHit,
    bodyTextSnippet: bodyText.slice(0, 300),
  };
}

