// Follow-up fix: the stepper's own value span is `aria-live="polite"` WITHOUT `aria-atomic`
// (see zimmQuantityStepper/index.tsx: `<chakra.span __css={styles.value} aria-live="polite">`).
// CartItemVariantPrice's own price/promo live region(s) also use aria-live="polite" but WITH
// aria-atomic="true" - confirmed live in run 1's strict-mode-violation error, which listed all 3
// matches verbatim. Disambiguate with :not([aria-atomic]).
const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const url = 'http://localhost:6006/iframe.html?id=commerce-productitem--default&viewMode=story';

  await page.goto(url, { waitUntil: 'load', timeout: 20000 });
  await page.getByRole('heading', { level: 2 }).first().waitFor({ state: 'visible', timeout: 10000 });
  await page.waitForTimeout(300);

  const dec = page.getByRole('button', { name: 'Decrease quantity' });
  const inc = page.getByRole('button', { name: 'Increase quantity' });
  const valueSpan = page.locator('span[aria-live="polite"]:not([aria-atomic])');

  const valueSpanCount = await valueSpan.count();

  const steps = [];
  const readState = async (label) => {
    const decAria = await dec.getAttribute('aria-disabled');
    const incAria = await inc.getAttribute('aria-disabled');
    const value = (await valueSpan.textContent())?.trim();
    const entry = { label, decAria, incAria, value };
    steps.push(entry);
    console.log(JSON.stringify(entry));
    return entry;
  };

  console.log('valueSpanCount:', valueSpanCount);

  await readState('initial (expect qty=1)');

  await dec.click();
  await page.waitForTimeout(200);
  await readState('after clicking decrement at floor (expect still qty=1)');

  await inc.click();
  await page.waitForTimeout(200);
  await readState('after 1st increment click (expect qty=2)');

  await inc.click();
  await page.waitForTimeout(200);
  await readState('after 2nd increment click (expect qty=3)');

  await inc.click();
  await page.waitForTimeout(200);
  await readState('after 3rd increment click at ceiling (expect still qty=3)');

  await browser.close();
  console.log('=====BOUNDARY_V2_DONE=====');
})().catch((err) => {
  console.error('SCRIPT_FATAL_ERROR', err);
  process.exitCode = 1;
});

